import { useState } from 'react';
import { JxTagInput, JxChip, JxDivider } from '@jinx-ui/react';

interface ArticleTagsProps {
  defaultTags?: string[];
  label?: string;
  onChange?: (tags: string[]) => void;
}

export default function ArticleTags({
  defaultTags = [],
  label = 'Теги статьи',
  onChange,
}: ArticleTagsProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const update = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'grid', gap: '12px' }}>
      <label
        className="jx-label"
        style={{ color: 'var(--jx-text)', fontFamily: 'var(--jx-font-sans)' }}
      >
        {label}
      </label>

      <JxTagInput
        ariaLabel={label}
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={update}
      />

      <JxDivider label={`Выбрано: ${tags.length}`} />

      {tags.length > 0 ? (
        <div
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
          aria-label="Выбранные теги"
        >
          {tags.map((tag) => (
            <JxChip
              key={tag}
              active
              removable
              onRemove={() => update(tags.filter((item) => item !== tag))}
            >
              {tag}
            </JxChip>
          ))}
        </div>
      ) : (
        <span style={{ color: 'var(--jx-text-3)', fontFamily: 'var(--jx-font-sans)' }}>
          Пока ни одного тега
        </span>
      )}
    </div>
  );
}

